initJs:
function(container, apiUrl, tables) {
    // 業務ロジックモジュールのインポート（グローバルスコープから取得）
    const {
        collectSalesData,
        classifySalesDataByProduct,
        classifySalesDataByStore,
        filterValidProductData,
        collectWeatherData,
        collectEventData,
        collectSeasonalData,
        analyzeCorrelationSalesWeather,
        analyzeCorrelationSalesEvent,
        analyzeCorrelationSalesSeason,
        compareWithHistoricalData,
        findAlternativeComparisonData,
        validateComparisonPeriod
    } = window.aiLogic || {};

    // 売上データ収集ボタン
    const collectSalesBtn = container.querySelector('#collectSalesBtn');
    if (collectSalesBtn) {
        collectSalesBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // APIから売上データを取得
                const salesResponse = await window.aivicApi.list('sales', {
                    startDate: startDate,
                    endDate: endDate
                });

                // 業務ロジックで処理
                const salesData = collectSalesData ? collectSalesData(salesResponse.data, startDate, endDate) : salesResponse.data;

                const tbody = container.querySelector('#salesDataTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    salesData.forEach(item => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = item.date || item.salesDate;
                        row.insertCell(1).textContent = item.productId;
                        row.insertCell(2).textContent = item.quantity;
                        row.insertCell(3).textContent = item.amount;
                    });
                }
                window.aivicNotify.success('売上データを収集しました');
            } catch (error) {
                window.aivicNotify.error('売上データの収集に失敗しました: ' + error.message);
            }
        });
    }

    // 商品別分析ボタン
    const analyzeByProductBtn = container.querySelector('#analyzeByProductBtn');
    if (analyzeByProductBtn) {
        analyzeByProductBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // APIから売上データを取得
                const salesResponse = await window.aivicApi.list('sales', {
                    startDate: startDate,
                    endDate: endDate
                });

                // 業務ロジックで商品別分析
                const productAnalysis = classifySalesDataByProduct ? classifySalesDataByProduct(salesResponse.data) : {};

                const tbody = container.querySelector('#productAnalysisTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    Object.entries(productAnalysis).forEach(([productId, data]) => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = productId;
                        row.insertCell(1).textContent = data.totalQuantity || 0;
                        row.insertCell(2).textContent = data.totalAmount || 0;
                        row.insertCell(3).textContent = data.averageAmount || 0;
                    });
                }
                window.aivicNotify.success('商品別分析を完了しました');
            } catch (error) {
                window.aivicNotify.error('商品別分析に失敗しました: ' + error.message);
            }
        });
    }

    // 店舗別分析ボタン
    const analyzeByStoreBtn = container.querySelector('#analyzeByStoreBtn');
    if (analyzeByStoreBtn) {
        analyzeByStoreBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // APIから売上データを取得
                const salesResponse = await window.aivicApi.list('sales', {
                    startDate: startDate,
                    endDate: endDate
                });

                // 業務ロジックで店舗別分析
                const storeAnalysis = classifySalesDataByStore ? classifySalesDataByStore(salesResponse.data) : {};

                const tbody = container.querySelector('#storeAnalysisTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    Object.entries(storeAnalysis).forEach(([storeId, data]) => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = storeId;
                        row.insertCell(1).textContent = data.totalQuantity || 0;
                        row.insertCell(2).textContent = data.totalAmount || 0;
                        row.insertCell(3).textContent = data.averageAmount || 0;
                    });
                }
                window.aivicNotify.success('店舗別分析を完了しました');
            } catch (error) {
                window.aivicNotify.error('店舗別分析に失敗しました: ' + error.message);
            }
        });
    }

    // 天気相関分析ボタン
    const analyzeWeatherBtn = container.querySelector('#analyzeWeatherBtn');
    if (analyzeWeatherBtn) {
        analyzeWeatherBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // APIから売上データと天気データを取得
                const [salesResponse, weatherResponse] = await Promise.all([
                    window.aivicApi.list('sales', { startDate, endDate }),
                    window.aivicApi.list('weather', { startDate, endDate })
                ]);

                // 業務ロジックで天気データ収集と相関分析
                const weatherData = collectWeatherData ? collectWeatherData(weatherResponse.data, startDate, endDate) : weatherResponse.data;
                const correlation = analyzeCorrelationSalesWeather ? analyzeCorrelationSalesWeather(salesResponse.data, weatherData) : {};

                const tbody = container.querySelector('#weatherCorrelationTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    Object.entries(correlation).forEach(([key, value]) => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = key;
                        row.insertCell(1).textContent = typeof value === 'number' ? value.toFixed(3) : value;
                    });
                }
                window.aivicNotify.success('天気相関分析を完了しました');
            } catch (error) {
                window.aivicNotify.error('天気相関分析に失敗しました: ' + error.message);
            }
        });
    }

    // イベント相関分析ボタン
    const analyzeEventBtn = container.querySelector('#analyzeEventBtn');
    if (analyzeEventBtn) {
        analyzeEventBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // APIから売上データとイベントデータを取得
                const [salesResponse, eventResponse] = await Promise.all([
                    window.aivicApi.list('sales', { startDate, endDate }),
                    window.aivicApi.list('events', { startDate, endDate })
                ]);

                // 業務ロジックでイベントデータ収集と相関分析
                const eventData = collectEventData ? collectEventData(eventResponse.data, startDate, endDate) : eventResponse.data;
                const correlation = analyzeCorrelationSalesEvent ? analyzeCorrelationSalesEvent(salesResponse.data, eventData) : {};

                const tbody = container.querySelector('#eventCorrelationTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    Object.entries(correlation).forEach(([key, value]) => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = key;
                        row.insertCell(1).textContent = typeof value === 'number' ? value.toFixed(3) : value;
                    });
                }
                window.aivicNotify.success('イベント相関分析を完了しました');
            } catch (error) {
                window.aivicNotify.error('イベント相関分析に失敗しました: ' + error.message);
            }
        });
    }

    // 季節相関分析ボタン
    const analyzeSeasonBtn = container.querySelector('#analyzeSeasonBtn');
    if (analyzeSeasonBtn) {
        analyzeSeasonBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // APIから売上データを取得
                const salesResponse = await window.aivicApi.list('sales', { startDate, endDate });

                // 業務ロジックで季節データ収集と相関分析
                const seasonalData = collectSeasonalData ? collectSeasonalData(startDate, endDate) : [];
                const correlation = analyzeCorrelationSalesSeason ? analyzeCorrelationSalesSeason(salesResponse.data, seasonalData) : {};

                const tbody = container.querySelector('#seasonCorrelationTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    Object.entries(correlation).forEach(([key, value]) => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = key;
                        row.insertCell(1).textContent = typeof value === 'number' ? value.toFixed(3) : value;
                    });
                }
                window.aivicNotify.success('季節相関分析を完了しました');
            } catch (error) {
                window.aivicNotify.error('季節相関分析に失敗しました: ' + error.message);
            }
        });
    }

    // 履歴比較ボタン
    const compareHistoryBtn = container.querySelector('#compareHistoryBtn');
    if (compareHistoryBtn) {
        compareHistoryBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;
                const comparisonPeriod = container.querySelector('#comparisonPeriod')?.value;

                if (!startDate || !endDate || !comparisonPeriod) {
                    window.aivicNotify.error('開始日、終了日、比較期間を入力してください');
                    return;
                }

                // 業務ロジックで比較期間の妥当性チェック
                const isValidPeriod = validateComparisonPeriod ? validateComparisonPeriod(startDate, endDate, comparisonPeriod) : true;
                if (!isValidPeriod) {
                    window.aivicNotify.error('比較期間が無効です');
                    return;
                }

                // APIから現在と過去の売上データを取得
                const [currentResponse, historicalResponse] = await Promise.all([
                    window.aivicApi.list('sales', { startDate, endDate }),
                    window.aivicApi.list('sales', { comparisonPeriod })
                ]);

                // 業務ロジックで履歴比較
                const comparison = compareWithHistoricalData ? compareWithHistoricalData(currentResponse.data, historicalResponse.data, comparisonPeriod) : {};

                const tbody = container.querySelector('#historyComparisonTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    Object.entries(comparison).forEach(([key, value]) => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = key;
                        row.insertCell(1).textContent = typeof value === 'number' ? value.toFixed(2) : value;
                    });
                }
                window.aivicNotify.success('履歴比較を完了しました');
            } catch (error) {
                window.aivicNotify.error('履歴比較に失敗しました: ' + error.message);
            }
        });
    }

    // データ検証ボタン
    const validateDataBtn = container.querySelector('#validateDataBtn');
    if (validateDataBtn) {
        validateDataBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // APIから商品データを取得
                const productResponse = await window.aivicApi.list('products', { startDate, endDate });

                // 業務ロジックでデータ検証
                const validData = filterValidProductData ? filterValidProductData(productResponse.data) : productResponse.data;
                const invalidCount = productResponse.data.length - validData.length;

                const resultDiv = container.querySelector('#validationResult');
                if (resultDiv) {
                    resultDiv.innerHTML = `
                        <p>総データ数: ${productResponse.data.length}</p>
                        <p>有効データ数: ${validData.length}</p>
                        <p>無効データ数: ${invalidCount}</p>
                    `;
                }
                window.aivicNotify.success('データ検証を完了しました');
            } catch (error) {
                window.aivicNotify.error('データ検証に失敗しました: ' + error.message);
            }
        });
    }

    // 代替データ検索ボタン
    const findAlternativeBtn = container.querySelector('#findAlternativeBtn');
    if (findAlternativeBtn) {
        findAlternativeBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;
                const criteria = container.querySelector('#alternativeCriteria')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // APIから売上データを取得
                const salesResponse = await window.aivicApi.list('sales', { startDate, endDate });

                // 業務ロジックで代替データ検索
                const alternativeData = findAlternativeComparisonData ? findAlternativeComparisonData(salesResponse.data, criteria) : [];

                const tbody = container.querySelector('#alternativeDataTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    alternativeData.forEach(item => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = item.date || item.period;
                        row.insertCell(1).textContent = item.similarity || 0;
                        row.insertCell(2).textContent = item.reason || '';
                    });
                }
                window.aivicNotify.success('代替データ検索を完了しました');
            } catch (error) {
                window.aivicNotify.error('代替データ検索に失敗しました: ' + error.message);
            }
        });
    }
}
